CREATE TABLE IF NOT EXISTS users (id VARCHAR(24) CHARACTER SET ascii PRIMARY KEY, username VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, pass_hash VARCHAR(255) NOT NULL, is_owner TINYINT NOT NULL DEFAULT 0, active TINYINT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, last_login DATETIME NULL, sess_ver INT NOT NULL DEFAULT 0, pendente TINYINT NOT NULL DEFAULT 0, pedido_em DATETIME NULL, must_change TINYINT NOT NULL DEFAULT 0, temp_expires DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS docs (path VARCHAR(700) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, col VARCHAR(700) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, data LONGTEXT NULL, version INT NOT NULL DEFAULT 1, seq BIGINT NOT NULL, deleted TINYINT NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL, updated_by VARCHAR(24) CHARACTER SET ascii NULL, KEY ix_seq (seq), KEY ix_col (col(191))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS seqgen (id BIGINT AUTO_INCREMENT PRIMARY KEY) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS locks (path VARCHAR(700) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, holder VARCHAR(100) NOT NULL, expires BIGINT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS files (id VARCHAR(40) CHARACTER SET ascii PRIMARY KEY, mime VARCHAR(60) NOT NULL, size INT NOT NULL, uid VARCHAR(24) CHARACTER SET ascii NOT NULL, created_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_falhas (id BIGINT AUTO_INCREMENT PRIMARY KEY, ip VARCHAR(45) NOT NULL, username VARCHAR(60) NOT NULL, em DATETIME NOT NULL, KEY ix_ip (ip), KEY ix_u (username)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS eventos_seg (id BIGINT AUTO_INCREMENT PRIMARY KEY, tipo VARCHAR(40) NOT NULL, uid VARCHAR(24) CHARACTER SET ascii NULL, ip VARCHAR(45) NOT NULL, ua VARCHAR(200) NULL, detalhe VARCHAR(300) NULL, em DATETIME NOT NULL, KEY ix_em (em), KEY ix_tipo (tipo)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS ajustes (k VARCHAR(40) PRIMARY KEY, v VARCHAR(200) NOT NULL) ENGINE=InnoDB;
